q:
Let $ABCDE$ be a regular pentagon, and let $F$ be the intersection of segments $BE$ and $AC$. A line through $F$ meets sides $AB$ and $CD$ at $G$ and $H$, respectively, with $BG=4$ and $CH=5$. Find the length of segment $AG$. Here $XY$ denotes the length of segment $XY$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
real cross2(pair u,pair v) {return u.x*v.y-u.y*v.x;}
pair meet(pair p,pair v,pair q,pair w) {return p+cross2(q-p,w)/cross2(v,w)*v;}
size(270);
pair[] V;for(int k=0;k<5;++k)V.push(dir(90+72*k));
pair A=V[0],B=V[1],C=V[2],D=V[3],E=V[4];
pair F=meet(B,E-B,A,C-A),G=A+0.4*(B-A),H=meet(G,F-G,C,D-C);
draw(A--B--C--D--E--cycle);draw(A--C);draw(B--E);draw(G--H);
label("A",A,(0,1));label("B",B,(-1,0));label("C",C,(-1,-1));label("D",D,(1,-1));label("E",E,(1,0));
label("F",F,(1,-1));label("G",G,(-1,1));label("H",H,(0,-1));
[/asy]
